"use client";

import { useEffect, useState } from "react";
import { Bell } from "lucide-react";
import {
  getNotifications,
  markNotificationsRead,
} from "@/services/notificationAPI";
import { useSocket } from "@/contexts/SocketContext";

export default function NotificationBell() {
  const [notifications, setNotifications] = useState([]);
  const [open, setOpen] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const socket = useSocket(); // ✅ Correct: use directly, not destructure

  // ✅ Fetch notifications once on load
  useEffect(() => {
    fetchNotifications();
  }, []);

  // ✅ Handle real-time notifications
  useEffect(() => {
    if (!socket) return;

    const handleNewNotification = (newNotification) => {
      setNotifications((prev) => [newNotification, ...prev]);
      setUnreadCount((prev) => prev + 1);
    };

    socket.on("notification", handleNewNotification);

    return () => {
      socket.off("notification", handleNewNotification);
    };
  }, [socket]);

  // ✅ Safe fetching with fallback for undefined
  const fetchNotifications = async () => {
    try {
      const res = await getNotifications();

      const notificationList = res?.data?.notifications || []; // ✅ fallback
      setNotifications(notificationList);

      const unread = notificationList.filter((n) => !n.read).length;
      setUnreadCount(unread);
    } catch (err) {
      console.error("Error fetching notifications", err);
      setNotifications([]); // ✅ fallback
      setUnreadCount(0);
    }
  };

  // ✅ Toggle and mark read
  const handleBellClick = async () => {
    setOpen(!open);
    if (unreadCount > 0) {
      await markNotificationsRead();
      setUnreadCount(0);
    }
  };

  return (
    <div className="relative">
      <button onClick={handleBellClick} className="relative">
        <Bell className="w-6 h-6 text-gray-300 hover:text-blue-400 transition" />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full px-1">
            {unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 mt-2 w-72 bg-white text-black shadow-md rounded-md z-50 max-h-96 overflow-y-auto">
          <ul>
            {!notifications || notifications.length === 0 ? (
              <li className="p-4 text-center text-gray-500">
                No notifications
              </li>
            ) : (
              notifications.map((n, i) => (
                <li key={i} className="p-3 border-b text-sm hover:bg-gray-100">
                  {n.message}
                </li>
              ))
            )}
          </ul>
        </div>
      )}
    </div>
  );
}
